    if (['tengames', 'tenrank', 'tenplayers', 'tensim', 'tenperf', 'tenbrief', 'tenask', 'tenmodel'].indexOf(nav) >= 0) return nav + '/' + tenTour();
    if (!clubsOn()) return NAV_HASH[nav];
