    var ang = function (i) { return -Math.PI / 2 + (2 * Math.PI * i) / n; };
    var pol = function (r, a) { return [(cx + r * Math.cos(a)).toFixed(1), (cy + r * Math.sin(a)).toFixed(1)]; };
