        // el guard a los 12s y se reintenta solo; el render se refresca al llegar (línea de abajo).
        if (!j || !(j.leagues || []).length) {
          setTimeout(function () { S.clubs = undefined; loadClubs(); }, 12000);
        }
        S.clubs = j || { leagues: [] };
