        S.clubNames = {};
        (S.clubs.leagues || []).forEach(function (L) { (L.table || []).forEach(function (tm) { S.clubNames[tm.id] = tm.name; }); });
        // re-render de la vista actual si usa el selector de competición y se abrió antes de tener las ligas
