    // Mundial + ligas intercalados por fecha; una liga = su cartelera. DEFAULT = 'todos' (pedido de Alexis:
    // Partidos abre con todas las competiciones, no con el Mundial).
    if (clubsOn() && S.mComp == null) S.mComp = 'todos';
